package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.media.*;
import android.os.*;
import android.view.View;
import android.webkit.*;
import android.widget.*;
import androidx.core.content.FileProvider;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class VideoShareBrowserTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity activity;private File output;private final List<Instrumentation.ActivityMonitor> monitors=new ArrayList<>();private Map<String,?> prefs,history,folders;
 private static final String SOURCE="https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/245b693e64cf5b5b33bc2a5f491a607f6a435655/Onda/tests/fixtures/download.mp4";
 @Before public void before(){prefs=c.getSharedPreferences("downloads",0).getAll();history=c.getSharedPreferences(DownloadHistory.PREF,0).getAll();folders=c.getSharedPreferences(OndaFolders.PREF,0).getAll();c.getSharedPreferences("downloads",0).edit().clear().commit();c.getSharedPreferences(DownloadHistory.PREF,0).edit().clear().commit();c.getSharedPreferences(OndaFolders.PREF,0).edit().putBoolean("enabled",false).commit();}
 private void restore(String name,Map<String,?> values){SharedPreferences.Editor e=c.getSharedPreferences(name,0).edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){Object v=entry.getValue();String k=entry.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);}e.commit();}
 @After public void after(){for(Instrumentation.ActivityMonitor m:monitors)ins.removeMonitor(m);ins.runOnMainSync(()->{if(activity!=null)activity.finish();});ins.waitForIdleSync();restore("downloads",prefs);restore(DownloadHistory.PREF,history);restore(OndaFolders.PREF,folders);if(output!=null)output.delete();}
 private Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{boolean[] ready={false};for(int i=0;i<1200;i++){ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("Video share scenario timed out: "+c.getSharedPreferences("downloads",0).getString("status",""));}
 private void report(String kind,JSONObject data)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"video-share-"+kind+".json"))){out.write(data.toString(2).getBytes("UTF-8"));}}
 private File target()throws Exception{File dir=new File(c.getCacheDir(),"shares");if(!dir.isDirectory())assertTrue(dir.mkdirs());output=File.createTempFile("onda-video-flow-",".mp4",dir);return output;}
 @Test public void downloadsCompleteVideoThenSharesActualFileAndReusesCachedCopy()throws Exception{
  Uri destination=FileProvider.getUriForFile(c,c.getPackageName()+".share",target());AtomicReference<Intent> chooser=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_CREATE_DOCUMENT.equals(intent.getAction()))return new Instrumentation.ActivityResult(Activity.RESULT_OK,new Intent().setData(destination));if(Intent.ACTION_CHOOSER.equals(intent.getAction())){chooser.set(intent);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};monitors.add(monitor);ins.addMonitor(monitor);
  activity=ins.startActivitySync(new Intent(c,DownloadsActivity.class).putExtra(VideoShare.EXTRA,SOURCE).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->((LinearLayout)field(activity,"choices")).getChildCount()>0);ins.runOnMainSync(()->{try{LinearLayout choices=(LinearLayout)field(activity,"choices");assertEquals("Only MP4 choices in full-video mode",1,choices.getChildCount());choices.getChildAt(0).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!MediaDownloadService.activeDownload&&((Button)field(activity,"shareReady")).getVisibility()==View.VISIBLE);assertTrue(output.length()>1000);assertNull("No chooser without user's final tap",chooser.get());ins.runOnMainSync(()->{try{((Button)field(activity,"shareReady")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->chooser.get()!=null);Intent send=chooser.get().getParcelableExtra(Intent.EXTRA_INTENT);assertEquals("video/mp4",send.getType());assertNull(send.getStringExtra(Intent.EXTRA_TEXT));Uri stream=send.getParcelableExtra(Intent.EXTRA_STREAM);assertEquals("content",stream.getScheme());assertTrue((send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,send.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);MediaExtractor reader=new MediaExtractor();boolean video=false,audio=false;try{reader.setDataSource(c,stream,null);for(int i=0;i<reader.getTrackCount();i++){String mime=reader.getTrackFormat(i).getString(MediaFormat.KEY_MIME);video|=mime.startsWith("video/");audio|=mime.startsWith("audio/");}}finally{reader.release();}assertTrue(video);assertTrue(audio);
  DownloadHistory.Entry cached=VideoShare.cached(c,SOURCE);assertNotNull(cached);assertEquals(destination.toString(),cached.uri);ins.runOnMainSync(()->((DownloadsActivity)activity).onNewIntent(new Intent(c,DownloadsActivity.class).putExtra(VideoShare.EXTRA,SOURCE)));waitFor(()->((Button)field(activity,"shareReady")).getVisibility()==View.VISIBLE);ins.runOnMainSync(()->{try{assertEquals(0,((LinearLayout)field(activity,"choices")).getChildCount());assertEquals(destination.toString(),field(activity,"cachedShareUri"));}catch(Exception e){throw new RuntimeException(e);}});report("complete",new JSONObject().put("realServiceDownload",true).put("bytes",output.length()).put("actualVideoAndAudioTracks",true).put("nativeFileChooser",true).put("readOnlyContentGrant",true).put("cachedReuseWithoutReanalysis",true));
 }
 @Test public void completionCannotShareAnotherRequestOrAnIncompleteOperation()throws Exception{String first=UUID.randomUUID().toString(),second=UUID.randomUUID().toString();Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",target());VideoShare.complete(c,first,"mp4",uri,"One");assertEquals(uri.toString(),VideoShare.ready(c,first));assertEquals("",VideoShare.ready(c,second));c.getSharedPreferences("downloads",0).edit().putBoolean("busy",true).commit();assertEquals("",VideoShare.ready(c,first));c.getSharedPreferences("downloads",0).edit().putBoolean("busy",false).commit();VideoShare.complete(c,second,"mp3",uri,"Wrong format");assertEquals("",VideoShare.ready(c,second));assertEquals("https://www.youtube.com/watch?v=56xlZcT--xM",VideoShare.source("https://youtu.be/56xlZcT--xM?list=PLabcdefghi"));assertFalse(VideoShare.canFile("https://www.youtube.com/playlist?list=PLabcdefghi"));report("isolation",new JSONObject().put("requestScopedCompletion",true).put("noPartialOrAudioFileSharedAsVideo",true).put("videoPreferredOverPlaylist",true));}
 @Test public void officialTikTokBrowserHasDownloadAndBothShareChoicesAndClosesWhenHidden()throws Exception{String post="https://www.tiktok.com/@onda/video/7701117786302598408";activity=ins.startActivitySync(new Intent(c,PlatformBrowserActivity.class).putExtra("url",post).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->field(activity,"web")!=null);AtomicReference<Intent> download=new AtomicReference<>(),chooser=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent i){if(i.getComponent()!=null&&i.getComponent().getClassName().equals(DownloadsActivity.class.getName())){download.set(i);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}if(Intent.ACTION_CHOOSER.equals(i.getAction())){chooser.set(i);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};monitors.add(monitor);ins.addMonitor(monitor);ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");web.stopLoading();WebViewClient delegate=web.getWebViewClient();web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream("<html><title>Onda browser fixture</title><body>Public post</body></html>".getBytes()));}@Override public void onPageFinished(WebView w,String u){delegate.onPageFinished(w,u);}});web.loadUrl(post);assertFalse(web.getSettings().getAllowFileAccess());assertFalse(web.getSettings().getAllowContentAccess());assertTrue(web.getSettings().getMediaPlaybackRequiresUserGesture());}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->"Onda browser fixture".equals(((WebView)field(activity,"web")).getTitle()));ins.runOnMainSync(()->{try{Button button=(Button)field(activity,"download");assertTrue(button.isEnabled());button.performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->download.get()!=null);assertEquals(post,download.get().getStringExtra("analyze_media_link"));ins.runOnMainSync(()->{try{((Button)field(activity,"share")).performClick();AlertDialog dialog=(AlertDialog)field(activity,"shareDialog");assertEquals("Vídeo completo (MP4)",dialog.getListView().getAdapter().getItem(0));dialog.getListView().performItemClick(null,1,1);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->chooser.get()!=null);Intent send=chooser.get().getParcelableExtra(Intent.EXTRA_INTENT);assertEquals(post,send.getStringExtra(Intent.EXTRA_TEXT));ins.runOnMainSync(()->{try{Method pause=PlatformBrowserActivity.class.getDeclaredMethod("onPause"),stop=PlatformBrowserActivity.class.getDeclaredMethod("onStop");pause.setAccessible(true);stop.setAccessible(true);pause.invoke(activity);stop.invoke(activity);assertNull(field(activity,"web"));Method resume=PlatformBrowserActivity.class.getDeclaredMethod("onResume");resume.setAccessible(true);resume.invoke(activity);assertNotNull(field(activity,"web"));assertEquals(post,field(activity,"lastUrl"));}catch(Exception e){throw new RuntimeException(e);}});report("browser",new JSONObject().put("officialTikTokPage",true).put("nativeDownloadShortcut",true).put("fileAndLinkShareChoices",true).put("browserDestroyedWhenHidden",true).put("sourceRestoredOnResume",true));}
}
